import Stripe from 'stripe'
import { createClient } from '@/lib/supabase/server'
import { NextRequest } from 'next/server'

const PLAN_NAMES: Record<string, string> = {
  [process.env.STRIPE_PRICE_EMPLOYER_PRO ?? '']: 'Pro Tier',
  [process.env.STRIPE_PRICE_EMPLOYER_VISIONARY ?? '']: 'Visionary Enterprise',
  [process.env.STRIPE_PRICE_EMPLOYER_NEXUS ?? '']: 'Nexus Supreme',
  [process.env.STRIPE_PRICE_SEEKER_ELITE ?? '']: 'Elite Professional',
}

export async function POST(req: NextRequest) {
  if (!process.env.STRIPE_SECRET_KEY || !process.env.STRIPE_WEBHOOK_SECRET) {
    return Response.json({ error: 'Stripe is not configured.' }, { status: 503 })
  }

  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
    apiVersion: '2025-03-31.basil',
  })

  const body = await req.text()
  const signature = req.headers.get('stripe-signature')!

  let event: Stripe.Event

  try {
    event = stripe.webhooks.constructEvent(body, signature, process.env.STRIPE_WEBHOOK_SECRET)
  } catch (err: any) {
    console.error('Webhook signature verification failed:', err.message)
    return Response.json({ error: 'Invalid signature' }, { status: 400 })
  }

  const supabase = await createClient()

  switch (event.type) {
    case 'checkout.session.completed': {
      const session = event.data.object as Stripe.Checkout.Session
      const supabaseUid = session.metadata?.supabase_uid
      if (!supabaseUid) break

      const subscriptionId = session.subscription as string
      const subscription = await stripe.subscriptions.retrieve(subscriptionId)
      const priceId = subscription.items.data[0]?.price.id
      const planName = PLAN_NAMES[priceId] || 'Unknown Plan'

      await supabase
        .from('users')
        .update({
          subscription_status: 'active',
          subscription_plan: planName,
          stripe_subscription_id: subscriptionId,
        })
        .eq('auth_id', supabaseUid)
      break
    }

    case 'customer.subscription.updated': {
      const subscription = event.data.object as Stripe.Subscription
      const supabaseUid = subscription.metadata?.supabase_uid
      if (!supabaseUid) break

      const priceId = subscription.items.data[0]?.price.id
      const planName = PLAN_NAMES[priceId] || 'Unknown Plan'
      const status = subscription.status

      await supabase
        .from('users')
        .update({
          subscription_status: status,
          subscription_plan: status === 'active' ? planName : null,
          stripe_subscription_id: subscription.id,
        })
        .eq('auth_id', supabaseUid)
      break
    }

    case 'customer.subscription.deleted': {
      const subscription = event.data.object as Stripe.Subscription
      const supabaseUid = subscription.metadata?.supabase_uid
      if (!supabaseUid) break

      await supabase
        .from('users')
        .update({
          subscription_status: 'inactive',
          subscription_plan: null,
          stripe_subscription_id: null,
        })
        .eq('auth_id', supabaseUid)
      break
    }

    case 'invoice.payment_failed': {
      const invoice = event.data.object as Stripe.Invoice
      const customerId = invoice.customer as string
      const customer = await stripe.customers.retrieve(customerId) as Stripe.Customer
      const supabaseUid = customer.metadata?.supabase_uid
      if (!supabaseUid) break

      await supabase
        .from('users')
        .update({ subscription_status: 'past_due' })
        .eq('auth_id', supabaseUid)
      break
    }
  }

  return Response.json({ received: true })
}

import { createClient } from '@/lib/supabase/server'
import { redirect } from 'next/navigation'
import ApplicantReviewClient from '@/components/features/employer/ApplicantReviewClient'

export default async function JobApplicantsPage({ params }: { params: Promise<{ jobId: string }> }) {
  const supabase = await createClient()

  // In Next.js 15+, params is a Promise
  const { jobId } = await params;

  const { data: { user }, error: authError } = await supabase.auth.getUser()
  if (authError || !user) {
    redirect('/sign-in')
  }

  // 1. Fetch User Record
  const { data: userRecord } = await supabase
    .from('users')
    .select('id, user_type')
    .eq('auth_id', user.id)
    .single()

  if (!userRecord || (userRecord.user_type !== 'employer' && userRecord.user_type !== 'both')) {
    redirect('/dashboard/seeker')
  }

  // 2. Fetch Job details and ensure ownership
  const { data: job, error: jobError } = await supabase
    .from('jobs')
    .select('*')
    .eq('id', jobId)
    .eq('employer_id', userRecord.id)
    .single()

  if (jobError || !job) {
    redirect('/dashboard/employer/listings')
  }

  // 3. Fetch Bids for this job with seeker profile details
  const { data: bids, error: bidsError } = await supabase
    .from('bids')
    .select(`
      *,
      users:users!bidder_id (
        id,
        full_name,
        email,
        avatar_url,
        username
      )
    `)
    .eq('job_id', jobId)
    .order('created_at', { ascending: false })

  return (
    <main className="max-w-7xl mx-auto px-8 py-12">
      <ApplicantReviewClient job={job} bids={bids || []} />
    </main>
  )
}

